import React from 'react';

const Dashboard = ({ 
    stats, 
    notifications, 
    setActiveTab, 
    currentUser, 
    allMatches, 
    myMatches, 
    startChat, 
    handleExpressInterest, 
    viewUserProfile,
    onSearch
}) => {

    // Live Feed matching profiles logic
    const feedProfiles = allMatches ? allMatches.slice(0, 10) : []; // show top 10 recent
    const targetGender = currentUser?.gender?.toLowerCase() === 'male' ? 'Ladies' : 'Gentlemen';

    // Local state for search inputs
    const [searchMinAge, setSearchMinAge] = React.useState('');
    const [searchMaxAge, setSearchMaxAge] = React.useState('');
    const [searchTown, setSearchTown] = React.useState('');

    const handleSearchSubmit = () => {
        if (onSearch) {
            const minAge = searchMinAge || '25';
            const maxAge = searchMaxAge || '35';
            onSearch({ ageRange: `${minAge}-${maxAge}`, town: searchTown });
        } else {
            setActiveTab('search-matches');
        }
    };

    // Helper functions for conditional logic
    const isAcceptedMatch = (phone) => {
        return myMatches && myMatches.some(m => m.phone === phone || m.phone_number === phone);
    };

    const handleLogout = () => {
        window.location.reload();
    };

    return (
        <div style={{ padding: '30px', maxWidth: '1400px', margin: '0 auto', width: '100%' }}>
            {/* Welcome Header */}
            <div style={{ marginBottom: '30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px' }}>
                <h1 style={{ fontSize: '2.2rem', color: '#1f2937', margin: 0, fontWeight: '800' }}>
                    👋 Welcome, {currentUser?.name || 'User'}!
                </h1>
                <span style={{ backgroundColor: '#ecfdf5', color: '#10b981', padding: '8px 16px', borderRadius: '24px', fontSize: '0.95rem', fontWeight: '700', boxShadow: '0 2px 4px rgba(16, 185, 129, 0.1)' }}>
                    Status: Online 🟢
                </span>
            </div>

            {/* Top Stats Bar */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: '20px', marginBottom: '40px' }}>
                <StatCard 
                    icon="👥" 
                    title="Total Matches" 
                    value={stats?.totalMatches || 0} 
                    color="#e11d48"
                    onClick={() => setActiveTab('matches')} 
                />
                <StatCard 
                    icon="📬" 
                    title="Pending Requests" 
                    value={stats?.pendingRequests || 0} 
                    color="#f59e0b"
                    onClick={() => setActiveTab('requests')} 
                />
                <StatCard 
                    icon="💕" 
                    title="Accepted Matches" 
                    value={stats?.acceptedMatches || 0} 
                    color="#10b981"
                    onClick={() => setActiveTab('matches')} 
                />
                <StatCard 
                    icon="💬" 
                    title="Unread Messages" 
                    value={stats?.unreadMessages || 0} 
                    color="#3b82f6"
                    onClick={() => setActiveTab('chat')} 
                />
            </div>

            {/* Quick Search Section */}
            <div style={{ backgroundColor: 'white', padding: '24px', borderRadius: '20px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)', marginBottom: '40px', border: '1px solid #e2e8f0' }}>
                <h2 style={{ margin: '0 0 4px 0', fontSize: '1.4rem', color: '#0f172a', fontWeight: '800' }}>🔍 Quick Search</h2>
                <p style={{ margin: '0 0 20px 0', color: '#64748b', fontSize: '0.95rem' }}>Find your perfect match</p>

                <div style={{ display: 'flex', gap: '16px', alignItems: 'flex-end', flexWrap: 'wrap' }}>
                    <div style={{ flex: '1', minWidth: '100px' }}>
                        <label style={{ display: 'block', fontSize: '0.85rem', color: '#64748b', marginBottom: '8px', fontWeight: 'bold' }}>Age Range</label>
                        <input 
                            type="number" 
                            placeholder="25" 
                            value={searchMinAge} 
                            onChange={(e) => setSearchMinAge(e.target.value)} 
                            style={{ width: '100%', padding: '12px 16px', borderRadius: '12px', border: '1px solid #cbd5e1', fontSize: '1rem', outline: 'none' }} 
                        />
                    </div>
                    <div style={{ flex: '1', minWidth: '100px' }}>
                        <label style={{ display: 'block', fontSize: '0.85rem', color: 'transparent', marginBottom: '8px', fontWeight: 'bold' }}>-</label>
                        <input 
                            type="number" 
                            placeholder="35" 
                            value={searchMaxAge} 
                            onChange={(e) => setSearchMaxAge(e.target.value)} 
                            style={{ width: '100%', padding: '12px 16px', borderRadius: '12px', border: '1px solid #cbd5e1', fontSize: '1rem', outline: 'none' }} 
                        />
                    </div>
                    <div style={{ flex: '2', minWidth: '200px' }}>
                        <label style={{ display: 'block', fontSize: '0.85rem', color: 'transparent', marginBottom: '8px', fontWeight: 'bold' }}>Town</label>
                        <input 
                            type="text" 
                            placeholder="town" 
                            value={searchTown} 
                            onChange={(e) => setSearchTown(e.target.value)} 
                            style={{ width: '100%', padding: '12px 16px', borderRadius: '12px', border: '1px solid #cbd5e1', fontSize: '1rem', outline: 'none' }} 
                        />
                    </div>
                    <button 
                        onClick={handleSearchSubmit} 
                        style={{ flex: '1', minWidth: '120px', padding: '14px', backgroundColor: '#e11d48', color: 'white', border: 'none', borderRadius: '12px', cursor: 'pointer', fontSize: '1.1rem', fontWeight: 'bold', display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '8px' }}
                        onMouseOver={(e) => e.currentTarget.style.backgroundColor = '#be123c'}
                        onMouseOut={(e) => e.currentTarget.style.backgroundColor = '#e11d48'}
                    >
                        🔍 Search
                    </button>
                </div>
            </div>

            {/* Quick Action Navigation Menu */}
            <h2 style={{ fontSize: '1.4rem', color: '#374151', marginBottom: '20px', fontWeight: '700' }}>Quick Actions</h2>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '20px', marginBottom: '50px' }}>
                <ActionCard 
                    customIcon={
                        currentUser?.profile_picture_url ? (
                            <img src={currentUser.profile_picture_url} alt="Profile" style={{ width: '40px', height: '40px', borderRadius: '50%', objectFit: 'cover', border: '2px solid #e2e8f0' }} />
                        ) : (
                            <span style={{ fontSize: '2rem' }}>👤</span>
                        )
                    }
                    title="My Profile" 
                    desc="View and edit your profile" 
                    status={currentUser?.profile_status === 'Active' ? '✅ Complete' : '⏳ Incomplete'}
                    onClick={() => setActiveTab('profile')} 
                />
                <ActionCard 
                    icon="💌" 
                    title="My Requests" 
                    desc="People interested in you" 
                    onClick={() => setActiveTab('requests')} 
                />
                <ActionCard 
                    icon="💬" 
                    title="Chats" 
                    desc="Your conversations" 
                    status={`${stats?.unreadMessages || 0} unread`}
                    onClick={() => setActiveTab('chat')} 
                />
                <ActionCard 
                    icon="🚪" 
                    title="Logout" 
                    desc="Exit the application" 
                    onClick={handleLogout} 
                    isDanger={true}
                />
            </div>

            {/* Live Activity Feed (Landscape Table) */}
            <div style={{ backgroundColor: 'white', borderRadius: '16px', boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)', overflow: 'hidden', marginBottom: '50px' }}>
                <div style={{ padding: '20px 24px', borderBottom: '1px solid #e5e7eb', backgroundColor: '#f8fafc', display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '15px' }}>
                    <h2 style={{ margin: 0, fontSize: '1.25rem', color: '#0f172a', display: 'flex', alignItems: 'center', fontWeight: '700' }}>
                        <span style={{ display: 'inline-block', width: '10px', height: '10px', backgroundColor: '#10b981', borderRadius: '50%', marginRight: '12px', animation: 'pulse 2s infinite' }}></span>
                        Live Activity Feed
                    </h2>
                    <div style={{ fontSize: '0.9rem', color: '#64748b', fontWeight: '600', backgroundColor: '#f1f5f9', padding: '6px 16px', borderRadius: '20px' }}>
                        👥 Matching Profiles | <span style={{color: '#0f172a'}}>{feedProfiles.length} results</span> | Showing {targetGender}
                    </div>
                </div>

                <div style={{ overflowX: 'auto', maxHeight: '500px' }}>
                    {feedProfiles.length === 0 ? (
                        <div style={{ padding: '60px 20px', textAlign: 'center' }}>
                            <p style={{ color: '#94a3b8', fontSize: '1.1rem', margin: 0, fontWeight: '500' }}>No matching profiles found at the moment.</p>
                        </div>
                    ) : (
                        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', fontSize: '0.95rem' }}>
                            <thead style={{ position: 'sticky', top: 0, backgroundColor: '#f8fafc', zIndex: 1, boxShadow: '0 1px 2px rgba(0,0,0,0.05)' }}>
                                <tr>
                                    <th style={thStyle}>#</th>
                                    <th style={thStyle}>Photo</th>
                                    <th style={thStyle}>Name</th>
                                    <th style={thStyle}>Age</th>
                                    <th style={thStyle}>Town</th>
                                    <th style={thStyle}>Marital Status</th>
                                    <th style={thStyle}>Occupation</th>
                                    <th style={thStyle}>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {feedProfiles.map((user, idx) => (
                                    <tr key={user.phone_number || idx} style={{ borderBottom: '1px solid #f1f5f9', transition: 'background-color 0.2s' }} onMouseOver={(e) => e.currentTarget.style.backgroundColor = '#f8fafc'} onMouseOut={(e) => e.currentTarget.style.backgroundColor = 'transparent'}>
                                        <td style={tdStyle}>{idx + 1}</td>
                                        <td style={tdStyle}>
                                            <div style={{ width: '40px', height: '40px', borderRadius: '50%', backgroundColor: '#e2e8f0', overflow: 'hidden', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                                                {user.profile_picture_url ? (
                                                    <img src={user.profile_picture_url} alt={user.full_name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                                ) : (
                                                    <span style={{ color: '#94a3b8', fontWeight: 'bold' }}>{user.full_name?.charAt(0)}</span>
                                                )}
                                            </div>
                                        </td>
                                        <td style={{ ...tdStyle, fontWeight: '700', color: '#1e293b' }}>{user.full_name || user.name || 'Unknown'}</td>
                                        <td style={{...tdStyle, color: '#64748b'}}>{user.age || 'N/A'}</td>
                                        <td style={{...tdStyle, color: '#64748b'}}>{user.town_name || user.town || 'N/A'}</td>
                                        <td style={{...tdStyle, color: '#64748b'}}>{user.marital_status || 'N/A'}</td>
                                        <td style={{...tdStyle, color: '#64748b'}}>{user.profession || user.occupation || 'N/A'}</td>
                                        <td style={tdStyle}>
                                            <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                                                <button 
                                                    onClick={() => viewUserProfile && viewUserProfile(user)} 
                                                    style={btnStyle('#f1f5f9', '#475569')}
                                                    onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
                                                    onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                                                >
                                                    👁️ View Profile
                                                </button>
                                                <button 
                                                    onClick={() => viewUserProfile && viewUserProfile(user)} 
                                                    style={btnStyle('#f8fafc', '#64748b', '1px solid #cbd5e1')}
                                                    onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
                                                    onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                                                >
                                                    📄 Description
                                                </button>
                                                {isAcceptedMatch(user.phone_number || user.phone) ? (
                                                    <button 
                                                        onClick={() => startChat && startChat({...user, name: user.full_name || user.name, phone: user.phone_number || user.phone})} 
                                                        style={btnStyle('#ecfdf5', '#10b981')}
                                                        onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
                                                        onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                                                    >
                                                        💬 Chat
                                                    </button>
                                                ) : (
                                                    <button 
                                                        onClick={() => handleExpressInterest && handleExpressInterest(user.phone_number || user.phone, user)} 
                                                        style={btnStyle('#fdf2f8', '#ec4899')}
                                                        onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
                                                        onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
                                                    >
                                                        ❤️ Express Interest
                                                    </button>
                                                )}
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    )}
                </div>
            </div>

            {/* Footer */}
            <div style={{ textAlign: 'center', color: '#94a3b8', fontSize: '0.85rem', fontWeight: '600', paddingBottom: '30px' }}>
                v2.0 • PENZI Dating Service
            </div>
        </div>
    );
};

// Reusable Sub-components

const StatCard = ({ icon, title, value, color, onClick }) => (
    <div 
        onClick={onClick}
        style={{ 
            backgroundColor: 'white', padding: '24px', borderRadius: '20px', 
            boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)', borderTop: `4px solid ${color}`, 
            cursor: 'pointer', transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)', display: 'flex', alignItems: 'center', gap: '20px',
            position: 'relative', overflow: 'hidden'
        }}
        onMouseOver={(e) => { e.currentTarget.style.transform = 'translateY(-6px)'; e.currentTarget.style.boxShadow = '0 20px 25px -5px rgba(0, 0, 0, 0.1)'; }}
        onMouseOut={(e) => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.boxShadow = '0 4px 6px -1px rgba(0, 0, 0, 0.05)'; }}
    >
        <div style={{ fontSize: '3rem', filter: 'drop-shadow(0 4px 6px rgba(0,0,0,0.1))' }}>{icon}</div>
        <div>
            <p style={{ margin: 0, fontSize: '2.5rem', fontWeight: '800', color: '#0f172a', lineHeight: '1' }}>{value}</p>
            <h3 style={{ margin: '8px 0 0 0', color: '#64748b', fontSize: '0.95rem', fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.5px' }}>{title}</h3>
        </div>
    </div>
);

const ActionCard = ({ icon, customIcon, title, desc, subDesc, status, onClick, isDanger, children }) => (
    <div 
        onClick={onClick}
        style={{ 
            backgroundColor: 'white', padding: '24px', borderRadius: '20px', 
            boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.05)', border: '1px solid #f1f5f9',
            cursor: 'pointer', transition: 'all 0.2s ease', display: 'flex', flexDirection: 'column'
        }}
        onMouseOver={(e) => { e.currentTarget.style.borderColor = isDanger ? '#fca5a5' : '#c4b5fd'; e.currentTarget.style.backgroundColor = isDanger ? '#fef2f2' : '#faf5ff'; e.currentTarget.style.transform = 'scale(1.02)'; }}
        onMouseOut={(e) => { e.currentTarget.style.borderColor = '#f1f5f9'; e.currentTarget.style.backgroundColor = 'white'; e.currentTarget.style.transform = 'scale(1)'; }}
    >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '16px' }}>
            {customIcon ? customIcon : <span style={{ fontSize: '2rem' }}>{icon}</span>}
            {status && (
                <span style={{ fontSize: '0.75rem', fontWeight: '700', padding: '6px 10px', borderRadius: '12px', backgroundColor: isDanger ? '#fee2e2' : '#f1f5f9', color: isDanger ? '#ef4444' : '#475569', border: `1px solid ${isDanger ? '#fca5a5' : '#e2e8f0'}` }}>
                    {status}
                </span>
            )}
        </div>
        <h3 style={{ margin: '0 0 6px 0', fontSize: '1.15rem', fontWeight: '800', color: isDanger ? '#ef4444' : '#0f172a' }}>{title}</h3>
        <p style={{ margin: 0, fontSize: '0.9rem', color: '#64748b', fontWeight: '500', lineHeight: '1.4' }}>{desc}</p>
        {subDesc && <p style={{ margin: '8px 0 0 0', fontSize: '0.8rem', color: '#94a3b8', fontWeight: '600' }}>{subDesc}</p>}
        {children && <div style={{ marginTop: '12px' }}>{children}</div>}
    </div>
);

// Styles
const thStyle = {
    padding: '16px 20px',
    color: '#64748b',
    fontWeight: '700',
    textTransform: 'uppercase',
    letterSpacing: '0.5px',
    fontSize: '0.75rem',
    borderBottom: '1px solid #e2e8f0'
};

const tdStyle = {
    padding: '20px',
    verticalAlign: 'middle',
    fontSize: '0.95rem'
};

const btnStyle = (bg, color) => ({
    padding: '8px 14px',
    backgroundColor: bg,
    color: color,
    border: 'none',
    borderRadius: '8px',
    fontWeight: '700',
    fontSize: '0.85rem',
    cursor: 'pointer',
    transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
});

export default Dashboard;
